<script setup lang="ts">
import { computed, ref } from 'vue'
import { backendDemo } from '../lib/backend-demo'
import { backendClient } from '../api/backend-client'
import PageHeading from '../components/PageHeading.vue'
import UiIcon from '../components/UiIcon.vue'
import InfoSheet from '../components/InfoSheet.vue'
import EmptyState from '../components/EmptyState.vue'
import CareerMatchPanel from '../components/CareerMatchPanel.vue'
import PanelTabs from '../components/PanelTabs.vue'
import ReadableText from '../components/ReadableText.vue'
import type { IntelItemView } from '../api/backend-types'
const query=ref(''),remoteQuery=ref(''),kind=ref('all'),mode=ref('facts'),status=ref(''),busy=ref(false),error=ref(''),reading=ref<IntelItemView|null>(null)
const items=computed(()=>backendDemo.state.intel.filter(i=>(kind.value==='all'||i.kind===kind.value)&&((i.title??'')+' '+(i.text??'')+' '+(i.kind_label??'')).includes(query.value.trim())))
const kinds=computed(()=>[...new Map(backendDemo.state.intel.map(i=>[i.kind??'other',i.kind_label??'其他资讯'])).entries()])
function sample(){backendDemo.loadIntelSample();status.value='已读取演示资讯；未发起远程检索。';error.value=''}
async function load(refresh=false){if(busy.value)return;busy.value=true;error.value='';try{const result=refresh?await backendClient.refreshIntel(remoteQuery.value.trim()):await backendClient.intel(remoteQuery.value.trim());if(!result||!Array.isArray(result.items))throw new Error('Incomplete intel');backendDemo.setIntel(result.items);query.value='';kind.value='all';status.value='已读取'+result.items.length+'条'+(backendDemo.state.dataMode==='demo'?'本地演示资料。':'最新资讯。')}catch{error.value='资讯没有读取成功，请重试。当前条目与筛选输入仍保留。'}finally{busy.value=false}}
function source(url?:string){return url&&/^https?:\/\//i.test(url)?url:undefined}
function read(id:string){const found=backendDemo.state.intel.find(i=>i.id===id);if(found)reading.value={...found}}
function facts(q:string){query.value=q;kind.value='all';mode.value='facts';status.value='已按「'+q+'」筛选现有资讯。没有对应条目时可在下方检索最新资讯。'}
</script>
<template><div class="ws-page intel-page"><PageHeading title="岗位资讯" description="阅读来源事实，再结合个人情况比较职业要求。"><button class="btn" @click="mode=mode==='match'?'facts':'match'">{{ mode==='match'?'返回资讯事实':'职业匹配' }}</button></PageHeading><PanelTabs v-model="mode" label="资讯与匹配视图" :items="[{key:'facts',label:'资讯事实'},{key:'match',label:'职业匹配'}]"><template v-if="mode==='facts'"><form class="remote-search" @submit.prevent="load()"><label class="ws-field">检索最新资讯<input v-model="remoteQuery" placeholder="职业、方向或关键词…" maxlength="200"/></label><button class="btn btn--primary" type="submit" :disabled="busy">{{ busy?'正在读取…':'检索' }}</button><button class="btn" type="button" :disabled="busy" @click="load(true)">刷新资讯</button></form><p v-if="error" class="ws-field-error" role="alert">{{ error }}</p><p v-if="status" class="desk-status" role="status">{{ status }}</p><div class="intel-toolbar"><label class="ws-field">筛选当前条目<input v-model="query" aria-label="筛选资讯" placeholder="只筛选当前已经读取的标题与内容…"/></label><label class="ws-field">内容类型<select v-model="kind"><option value="all">全部类型</option><option v-for="[key,label] in kinds" :key="key" :value="key">{{ label }}</option></select></label></div><div v-if="items.length" class="intel-list"><article v-for="item in items" :key="item.id" class="desk-intel-item"><div class="intel-meta"><span>{{ item.kind_label || '资讯' }}</span><time v-if="item.fetched_at">{{ new Date(item.fetched_at).toLocaleString('zh-CN') }}</time></div><h2><button class="intel-title" @click="reading={...item}">{{ item.title || '资讯正文' }}<UiIcon name="arrow" :size="18"/></button></h2><p>{{ item.text }}</p><div class="desk-intel-item__source"><a v-if="source(item.source_url)" class="ws-text-link" :href="source(item.source_url)" target="_blank" rel="noopener noreferrer">{{ item.source_name || '原始来源' }}<UiIcon name="arrow" :size="16"/></a><span v-else class="ws-muted">{{ item.source_name || '未提供原始来源链接' }}</span><button class="ws-text-button" @click="reading={...item}">阅读全文</button></div></article></div><EmptyState v-else kind="intel" :title="backendDemo.state.intel.length?'没有匹配的资讯':'暂无已读取资讯'" description="可调整筛选、检索最新资料，或先查看示例。"><button v-if="backendDemo.state.intel.length" class="btn" @click="query='';kind='all'">清除筛选</button><button v-else class="btn" @click="sample">加载资讯示例</button></EmptyState><p class="ws-demo-note">{{ backendDemo.state.intelOrigin==='live'&&backendDemo.state.dataMode==='service'?'条目来自本次服务读取；本地筛选不再发起远程请求。':'当前条目为演示示例；上方检索与刷新调用正式资讯服务，不会以示例替代失败结果。' }}</p></template></PanelTabs><CareerMatchPanel v-show="mode==='match'" :facts="backendDemo.state.intel" @read="read" @facts="facts"/><nav class="ws-related"><RouterLink to="/directions">对照方向方案</RouterLink><RouterLink to="/report">查看个人诊断</RouterLink></nav><InfoSheet :open="reading!==null" :title="reading?.title || '资讯详情'" wide @close="reading=null"><article class="reading-prose"><p class="ws-muted">{{ reading?.source_name || '来源未提供' }}<span v-if="reading?.fetched_at"> · {{ new Date(reading.fetched_at).toLocaleString('zh-CN') }}</span></p><ReadableText :text="reading?.text || '本条资讯未提供正文。'"/><a v-if="source(reading?.source_url)" class="ws-text-link" :href="source(reading?.source_url)" target="_blank" rel="noopener noreferrer">核对原始来源</a></article></InfoSheet></div></template>
